import { useEffect, useState } from 'react'
import { Link } from 'react-router-dom'
import { Alert, Button, Card, Col, DatePicker, Descriptions, Drawer, Empty, Form, Input, InputNumber, Modal, Popconfirm, Row, Select, Space, Table, Tabs, Tag, Tree, Typography, message } from 'antd'
import { ApartmentOutlined, AppstoreOutlined, BookOutlined, CheckCircleOutlined, MonitorOutlined, SafetyCertificateOutlined, SearchOutlined, ThunderboltOutlined } from '@ant-design/icons'
import { api, Department, Profile, User } from './api/client'
import { useI18n } from './i18n'
import { RelationTags } from './UxComponents'

const { Text, Title } = Typography
const flattenDepartments = (nodes: Department[]): Department[] => nodes.flatMap((n) => [n, ...(n.children ? flattenDepartments(n.children) : [])])
const statusColor = (value: string) => ['active', 'running', 'completed', 'published', 'healthy', 'indexed', 'approved'].includes(value) ? 'green' : ['critical', 'high', 'error', 'failed', 'disabled', 'rejected', 'cancelled'].includes(value) ? 'red' : 'gold'
const V21Status = ({ value }: { value?: string }) => <Tag color={statusColor(value || 'unknown')}>{(value || 'unknown').replaceAll('_', ' ')}</Tag>
const V21Error = ({ error }: { error: unknown }) => error ? <Alert type="error" showIcon message={(error as any)?.code || (error as Error).message || 'Request failed'} style={{ marginBottom: 16 }} /> : null
const page = (title: string, subtitle: React.ReactNode, action?: React.ReactNode) => <div className="page-heading"><div><h1 className="page-title">{title}</h1><div className="page-subtitle">{subtitle}</div></div>{action}</div>

/** Shared selector used by Roles, Users, Departments, Skills and Knowledge. */
export function SearchMultiSelect({ options, value, onChange, placeholder, disabled }: { options: { value: string | number; label: React.ReactNode; disabled?: boolean }[]; value?: (string | number)[]; onChange?: (value: any[]) => void; placeholder?: string; disabled?: boolean }) {
  return <Select mode="multiple" showSearch allowClear optionFilterProp="label" suffixIcon={<SearchOutlined />} style={{ width: '100%' }} options={options} value={value} onChange={onChange} placeholder={placeholder} disabled={disabled} />
}

export function DashboardV21() {
  const { t, formatDate } = useI18n(); const [data, setData] = useState<any>(); const [notifications, setNotifications] = useState<any[]>([]); const [error, setError] = useState<unknown>(); const [lastUpdated, setLastUpdated] = useState<string>(); const [loading, setLoading] = useState(false)
  const load = async () => { if (loading) return; setLoading(true); try { const [d, n] = await Promise.all([api.get<any>("/dashboard/v3"), api.get<any[]>("/notifications")]); setData(d); setNotifications(n); setLastUpdated(new Date().toISOString()); setError(undefined) } catch (e) { setError(e) } finally { setLoading(false) } }
  useEffect(() => { void load(); const refresh = () => { void load() }; window.addEventListener("hep:refresh", refresh); return () => window.removeEventListener("hep:refresh", refresh) }, [])
  const metrics = [[t("totalUsers"), data?.total_users, <ApartmentOutlined />], [t("activeUsers"), data?.active_users, <CheckCircleOutlined />], [t("highRisk"), data?.high_critical_executions, <SafetyCertificateOutlined />], [t("pendingApprovals"), data?.pending_approvals, <CheckCircleOutlined />], [t("runtimeErrors"), data?.runtime_errors, <MonitorOutlined />], [t("tokenToday"), data?.token_today, <ThunderboltOutlined />]]
  const attention = [["critical_executions", t("critical"), "/executions"], ["high_risk_executions", t("highRisk"), "/executions"], ["pending_approvals", t("pendingApprovals"), "/approvals"], ["pending_skill_reviews", t("skillReviews"), "/skills"], ["runtime_failures", t("runtimeErrors"), "/runtimes"], ["budget_warnings", t("budgetWarnings"), "/quotas"]]
  return <>{page(t("overview"), <>{t("subtitle")} {lastUpdated && <Text type="secondary" className="last-updated">· Last updated {formatDate(lastUpdated)}</Text>}</>)}<V21Error error={error} /><Row gutter={[16, 16]}>{metrics.map(([label, value, icon]) => <Col xs={12} lg={4} key={String(label)}><Card className="stat-card"><div className="ant-statistic-title">{label}</div><Title level={2} style={{ margin: 0 }}>{Number(value || 0)}</Title><Text type="secondary">{icon}</Text></Card></Col>)}</Row><Row gutter={[16, 16]} style={{ marginTop: 16 }}><Col xs={24} lg={15}><Card className="content-card" title={t("attention")}><Space direction="vertical" style={{ width: "100%" }}>{attention.map(([key, label, path]) => Number(data?.attention_required?.[key as string] || 0) > 0 ? <Link to={path as string} key={key as string}><Alert type={key === "critical_executions" ? "error" : "warning"} showIcon message={String(label) + ": " + data.attention_required[key as string]} /></Link> : null)}</Space></Card></Col><Col xs={24} lg={9}><Card className="content-card" title={t("platformHealth")}><Space direction="vertical">{Object.entries(data?.platform_health || {}).map(([key, value]) => <Space key={key}><V21Status value={String(value)} /><Text>{key}</Text></Space>)}</Space></Card><Card className="content-card" title={t("notifications")} style={{ marginTop: 16 }}>{notifications.slice(0, 3).map((n) => <Alert key={n.id} type={n.type === "risk_event" ? "error" : "info"} message={n.title} description={n.body} style={{ marginBottom: 8 }} />)}</Card></Col></Row></>}

export function UsersV21() {
  const { t } = useI18n(); const [users, setUsers] = useState<User[]>([]); const [departments, setDepartments] = useState<Department[]>([]); const [roles, setRoles] = useState<any[]>([]); const [selected, setSelected] = useState<any>(); const [error, setError] = useState<unknown>(); const [open, setOpen] = useState(false); const [roleOpen, setRoleOpen] = useState(false); const [editing, setEditing] = useState<User>(); const [form] = Form.useForm(); const [roleForm] = Form.useForm()
  const load = () => Promise.all([api.get<User[]>('/users'), api.get<Department[]>('/departments/tree'), api.get<any[]>('/roles/manage')]).then(([u, d, r]) => { setUsers(u); setDepartments(d); setRoles(r) }).catch(setError); useEffect(() => { void load() }, [])
  const show = async (u: User) => { try { setSelected({ ...(await api.get<any>(`/users/${u.id}/summary`)), activity: await api.get<any[]>(`/users/${u.id}/activity`), effective: await api.get<any[]>(`/users/${u.id}/effective-permissions`) }) } catch (e) { setError(e) } }
  const close = () => { setOpen(false); setEditing(undefined); form.resetFields() }
  return <>{page(t('users'), t('organization'), <Button type="primary" onClick={() => { form.resetFields(); setEditing(undefined); setOpen(true) }}>{t('create')}</Button>)}<V21Error error={error} /><Card className="content-card"><Table rowKey="id" dataSource={users} scroll={{ x: 1100 }} columns={[{ title: t('name'), render: (_: unknown, r: User) => <Button type="link" onClick={() => show(r)}>{r.display_name}<div className="muted">@{r.username}</div></Button> }, { title: t('email'), dataIndex: 'email' }, { title: t('department'), dataIndex: 'department' }, { title: t('roles'), render: (_: unknown, r: User) => <Space wrap>{r.roles.map((x) => <Tag key={x}>{x}</Tag>)}</Space> }, { title: t('status'), render: (_: unknown, r: User) => <V21Status value={r.status} /> }, { title: t('actions'), render: (_: unknown, r: User) => <Space><Button size="small" onClick={() => { setEditing(r); form.setFieldsValue({ display_name: r.display_name, email: r.email }); setOpen(true) }}>{t('edit')}</Button><Button size="small" onClick={async () => { try { await api.post(`/users/${r.id}/status`, { status: r.status === 'active' ? 'suspended' : 'active' }); load() } catch (e) { setError(e) } }}>{r.status === 'active' ? t('suspend') : t('activate')}</Button></Space> }]} /></Card><Modal title={editing ? t('edit') : t('create')} open={open} onCancel={close} footer={null}><Form form={form} layout="vertical" onFinish={async (v) => { try { editing ? await api.put(`/users/${editing.id}`, v) : await api.post('/users', v); message.success(t('saved')); close(); load() } catch (e) { setError(e) } }}><Form.Item name="username" label={t('username')} rules={[{ required: !editing }]}><Input disabled={!!editing} /></Form.Item><Form.Item name="display_name" label={t('name')} rules={[{ required: true }]}><Input /></Form.Item><Form.Item name="email" label={t('email')} rules={[{ required: true }]}><Input /></Form.Item>{!editing && <Form.Item name="password" label={t('password')} rules={[{ required: true, min: 12 }]}><Input.Password /></Form.Item>}<Form.Item name="department_id" label={t('department')}><Select allowClear showSearch optionFilterProp="label" options={flattenDepartments(departments).map((d) => ({ value: d.id, label: d.name }))} /></Form.Item><Button type="primary" htmlType="submit" block>{t('save')}</Button></Form></Modal><Drawer width={900} title={`${t('details')} · ${selected?.display_name || ''}`} open={!!selected} onClose={() => setSelected(undefined)}>{selected && <Tabs items={[{ key: 'overview', label: t('overviewTab'), children: <Descriptions column={2} items={[{ key: '1', label: t('username'), children: selected.username }, { key: '2', label: t('email'), children: selected.email }, { key: '3', label: t('status'), children: <V21Status value={selected.status} /> }, { key: '4', label: t('department'), children: selected.department || '—' }, { key: '5', label: t('runtime'), children: selected.runtime_status }, { key: '6', label: t('profiles'), children: selected.profile_count }]} /> }, { key: 'roles', label: t('roles'), children: <><Button type="primary" onClick={() => { roleForm.resetFields(); setRoleOpen(true) }}>{t('assignRole')}</Button><Table size="small" rowKey={(r: any) => `${r.id}-${r.scope}`} dataSource={selected.roles} columns={[{ title: t('roles'), dataIndex: 'name' }, { title: t('scope'), dataIndex: 'scope' }, { title: t('department'), dataIndex: 'department' }, { title: t('createdAt'), dataIndex: 'created_at' }, { title: t('actions'), render: (_: unknown, r: any) => <Popconfirm title={t('delete')} onConfirm={async () => { await api.delete(`/users/${selected.id}/roles/${r.id}`); show(selected); load() }}><Button danger size="small">{t('delete')}</Button></Popconfirm> }]} /></> }, { key: 'profiles', label: t('profiles'), children: <Table size="small" rowKey="id" dataSource={selected.profiles || []} columns={[{ title: t('name'), dataIndex: 'display_name' }, { title: t('version'), dataIndex: 'template_version' }]} /> }, { key: 'runtime', label: t('runtime'), children: <Space direction="vertical"><Text>{selected.runtime_status}</Text>{selected.runtime_id && <Link to={`/runtimes?id=${selected.runtime_id}`}>{t('details')}</Link>}</Space> }, { key: 'permissions', label: t('effectivePermissions'), children: <Table size="small" rowKey={(r: any) => `${r.permission}-${r.source_role}-${r.scope}`} dataSource={selected.effective} columns={[{ title: t('permission'), dataIndex: 'permission' }, { title: t('sourceRole'), dataIndex: 'source_role' }, { title: t('scope'), dataIndex: 'scope' }, { title: t('sourceBinding'), dataIndex: 'source_binding' }]} /> }, { key: 'activity', label: t('activity'), children: <Table size="small" rowKey="created_at" dataSource={selected.activity} columns={[{ title: t('actions'), dataIndex: 'action' }, { title: t('resource'), dataIndex: 'resource_type' }, { title: t('createdAt'), dataIndex: 'created_at' }]} /> }]} />}</Drawer><Modal title={t('assignRole')} open={roleOpen} onCancel={() => setRoleOpen(false)} footer={null}><Form form={roleForm} layout="vertical" onFinish={async (v) => { try { for (const rid of v.role_ids || []) await api.post(`/users/${selected.id}/roles`, { role_id: rid, scope: v.scope || 'user', department_id: v.department_id }); message.success(t('saved')); setRoleOpen(false); show(selected); load() } catch (e) { setError(e) } }}><Form.Item name="role_ids" label={t('roles')} rules={[{ required: true }]}><SearchMultiSelect options={roles.map((r) => ({ value: r.id, label: r.name }))} placeholder={t('search')} /></Form.Item><Form.Item name="scope" label={t('scope')} initialValue="user"><Select options={['global', 'organization', 'department', 'user', 'profile'].map((v) => ({ value: v, label: v }))} /></Form.Item><Form.Item name="department_id" label={t('department')}><Select allowClear options={flattenDepartments(departments).map((d) => ({ value: d.id, label: d.name }))} /></Form.Item><Button type="primary" htmlType="submit" block>{t('save')}</Button></Form></Modal></>
}

export function DepartmentsV21() {
  const { t } = useI18n(); const [data, setData] = useState<Department[]>([]); const [selected, setSelected] = useState<any>(); const [open, setOpen] = useState(false); const [editing, setEditing] = useState<any>(); const [templates, setTemplates] = useState<any[]>([]); const [form] = Form.useForm(); const [error, setError] = useState<unknown>()
  const load = () => Promise.all([api.get<Department[]>('/departments/tree'), api.get<any[]>('/runtime-templates')]).then(([d, r]) => { setData(d); setTemplates(r) }).catch(setError); useEffect(() => { void load() }, [])
  const edit = (value?: any, parent?: number) => { setEditing(value); form.resetFields(); if (value) form.setFieldsValue(value); if (parent) form.setFieldsValue({ parent_id: parent }); setOpen(true) }
  const tree = (nodes: Department[]): any[] => nodes.map((d) => ({ key: d.id, title: <Space><span>{d.name}</span><Tag>{d.member_count}</Tag><Button type="link" size="small" onClick={(e) => { e.stopPropagation(); edit(d) }}>{t('edit')}</Button><Button type="link" size="small" onClick={(e) => { e.stopPropagation(); edit(undefined, d.id) }}>{t('addChild')}</Button></Space>, children: tree(d.children || []) }))
  return <>{page(t('departments'), t('organization'), <Button type="primary" onClick={() => edit()}>{t('create')}</Button>)}<V21Error error={error} /><Row gutter={16}><Col xs={24} lg={14}><Card className="content-card"><Tree showLine defaultExpandAll treeData={tree(data)} /></Card></Col><Col xs={24} lg={10}><Card className="content-card"><Table size="small" rowKey="id" pagination={false} dataSource={flattenDepartments(data)} onRow={(r) => ({ onClick: async () => { try { setSelected(await api.get<any>(`/departments/${r.id}/detail`)) } catch (e) { setError(e) } } })} columns={[{ title: t('name'), dataIndex: 'name' }, { title: t('status'), render: (_: unknown, r: Department) => <V21Status value={r.status} /> }, { title: t('users'), dataIndex: 'member_count' }, { title: t('actions'), render: (_: unknown, r: Department) => <Space><Button size="small" onClick={() => edit(r)}>{t('edit')}</Button><Button size="small" onClick={async () => { await api.post(`/departments/${r.id}/status`, { status: r.status === 'disabled' ? 'active' : 'disabled' }); load() }}>{r.status === 'disabled' ? t('activate') : t('suspend')}</Button><Popconfirm title={t('delete')} onConfirm={async () => { try { await api.delete(`/departments/${r.id}/managed`); load() } catch (e) { setError(e) } }}><Button size="small" danger>{t('delete')}</Button></Popconfirm></Space> }]} /></Card></Col></Row><Drawer title={`${t('details')} · ${selected?.name || ''}`} open={!!selected} onClose={() => setSelected(undefined)}>{selected && <Tabs items={[{ key: 'overview', label: t('overviewTab'), children: <Descriptions column={1} items={[{ key: '1', label: t('name'), children: selected.name }, { key: '2', label: 'Code', children: selected.code }, { key: '3', label: t('status'), children: <V21Status value={selected.status} /> }, { key: '4', label: t('members'), children: selected.member_count }, { key: '5', label: t('defaultTemplate'), children: selected.default_runtime_template_id || '—' }]} /> }, { key: 'activity', label: t('activity'), children: <Empty image={Empty.PRESENTED_IMAGE_SIMPLE} description={t('empty')} /> }]} />}</Drawer><Modal title={editing ? t('edit') : t('create')} open={open} onCancel={() => setOpen(false)} footer={null}><Form form={form} layout="vertical" onFinish={async (v) => { try { editing ? await api.put(`/departments/${editing.id}/detail`, v) : await api.post('/departments/manage', v); message.success(t('saved')); setOpen(false); load() } catch (e) { setError(e) } }}><Form.Item name="name" label={t('name')} rules={[{ required: true }]}><Input /></Form.Item><Form.Item name="code" label="Code"><Input /></Form.Item><Form.Item name="description" label={t('description')}><Input.TextArea /></Form.Item><Form.Item name="parent_id" label={t('department')}><Select allowClear options={flattenDepartments(data).filter((d) => !editing || d.id !== editing.id).map((d) => ({ value: d.id, label: d.name }))} /></Form.Item><Form.Item name="default_runtime_template_id" label={t('defaultTemplate')}><Select allowClear options={templates.map((x) => ({ value: x.id, label: x.name }))} /></Form.Item><Button type="primary" htmlType="submit" block>{t('save')}</Button></Form></Modal></>
}

export function AgentTemplatesV21() {
  const { t } = useI18n(); const templateID = Number(new URLSearchParams(window.location.search).get("id")); const [data, setData] = useState<any[]>([]); const [skills, setSkills] = useState<any[]>([]); const [knowledge, setKnowledge] = useState<any[]>([]); const [models, setModels] = useState<any[]>([]); const [detail, setDetail] = useState<any>(); const [open, setOpen] = useState(false); const [editing, setEditing] = useState<number>(); const [form] = Form.useForm(); const [error, setError] = useState<unknown>()
  const load = () => Promise.all([api.get<any[]>('/agent-templates'), api.get<any[]>('/skills'), api.get<any[]>('/knowledge-bases'), api.get<any[]>('/models')]).then(([a, s, k, m]) => { setData(a); setSkills(s); setKnowledge(k); setModels(m) }).catch(setError); useEffect(() => { void load() }, [])
  const show = async (id: number) => { try { setDetail(await api.get<any>(`/agent-templates/${id}`)) } catch (e) { setError(e) } }
  useEffect(() => { if (templateID) void show(templateID) }, [templateID])
  const editTemplate = async (id: number) => { try { const value = await api.get<any>('/agent-templates/' + id); setDetail(value); setEditing(id); form.setFieldsValue(value); setOpen(true) } catch (e) { setError(e) } }
  return <>{page(t('agentTemplates'), t('agentTemplateBoundary'), <Button type="primary" icon={<AppstoreOutlined />} onClick={() => { form.resetFields(); setEditing(undefined); setOpen(true) }}>{t('create')}</Button>)}<V21Error error={error} /><Card className="content-card"><Table rowKey="id" dataSource={data} columns={[{ title: t('name'), render: (_: unknown, r: any) => <Space><Button type="link" onClick={() => show(r.id)}>{r.display_name}</Button><Button size="small" onClick={() => editTemplate(r.id)}>{t('edit')}</Button></Space> }, { title: t('version'), dataIndex: 'template_version', render: (v) => `v${v}` }, { title: 'Associated Roles', render: (_: unknown, r: any) => <RelationTags values={r.associated_roles} /> }, { title: 'Profiles / Instances', render: (_: unknown, r: any) => <RelationTags values={r.instance_names} max={2} /> }, { title: t('status'), render: (_: unknown, r: any) => <V21Status value={r.status} /> }]} /></Card><Modal title={t('agentTemplates')} open={open} onCancel={() => setOpen(false)} footer={null} width={720}><Form form={form} layout="vertical" onFinish={async (v) => { try { const payload = { ...v, default_skills: v.default_skills || [], default_knowledge: v.default_knowledge || [], skill_policies: Object.fromEntries((v.default_skills || []).map((x: string) => [x, 'default'])) }; if (editing) await api.put('/agent-templates/' + editing, payload); else await api.post('/agent-templates', payload); message.success(t('created')); setOpen(false); load() } catch (e) { setError(e) } }}><Form.Item name="name" label={t('name')} rules={[{ required: true }]}><Input /></Form.Item><Form.Item name="display_name" label={t('displayName')} rules={[{ required: true }]}><Input /></Form.Item><Form.Item name="description" label={t('description')}><Input.TextArea /></Form.Item><Form.Item name="default_model_id" label={t('defaultModel')}><Select showSearch optionFilterProp="label" options={models.map((x) => ({ value: x.id, label: `${x.display_name} · ${x.provider}` }))} /></Form.Item><Form.Item name="default_skills" label={t('defaultSkills')}><SearchMultiSelect options={skills.map((x) => ({ value: x.name, label: `${x.display_name} · ${x.category} · ${x.risk_level || x.risk}` }))} placeholder={t('search')} /></Form.Item><Form.Item name="default_knowledge" label={t('defaultKnowledge')}><SearchMultiSelect options={knowledge.map((x) => ({ value: x.name, label: `${x.name} · ${x.owner_department || ''}` }))} placeholder={t('search')} /></Form.Item><Button type="primary" htmlType="submit" block>{t('save')}</Button></Form></Modal><Drawer width={1000} title={`${t('details')} · ${detail?.display_name || ''}`} open={!!detail} onClose={() => setDetail(undefined)}>{detail && <Tabs items={[{ key: 'overview', label: t('overviewTab'), children: <Descriptions column={1} items={[{ key: '1', label: t('description'), children: detail.description }, { key: '2', label: t('version'), children: `v${detail.template_version}` }, { key: '3', label: t('profileType'), children: detail.managed ? t('managed') : t('personal') }]} /> }, { key: 'assignments', label: t('assignments'), children: <AssignmentPanel detail={detail} onChange={() => show(detail.id)} /> }, { key: 'model', label: t('models'), children: <Space wrap>{(detail.default_skills || []).map((x: string) => <Tag key={x}>{x}</Tag>)}{(detail.default_knowledge || []).map((x: string) => <Tag color="blue" key={x}>{x}</Tag>)}</Space> }, { key: 'instances', label: t('instances'), children: <Table size="small" rowKey="profile_id" dataSource={detail.instances} columns={[{ title: t('owner'), dataIndex: 'user' }, { title: t('profiles'), dataIndex: 'agent_profile' }, { title: t('template'), render: (_: unknown, r: any) => `v${r.template_version}` }, { title: t('status'), render: (_: unknown, r: any) => <V21Status value={r.status} /> }]} /> }, { key: 'history', label: t('changeHistory'), children: <Empty image={Empty.PRESENTED_IMAGE_SIMPLE} description={t('empty')} /> }]} />}</Drawer></>
}

function AssignmentPanel({ detail, onChange }: { detail: any; onChange: () => void }) { const { t } = useI18n(); const [source, setSource] = useState('department'); const [ids, setIds] = useState<(string | number)[]>([]); const [options, setOptions] = useState<any[]>([]); useEffect(() => { const path = source === 'department' ? '/departments/tree' : source === 'role' ? '/roles/manage' : '/users'; api.get<any>(path).then((v) => setOptions(source === 'department' ? flattenDepartments(v) : v)).catch(() => undefined) }, [source]); return <><Space style={{ marginBottom: 16 }}><Select value={source} onChange={(v) => { setSource(v); setIds([]) }} options={['department', 'role', 'user', 'organization'].map((v) => ({ value: v, label: v }))} /><SearchMultiSelect value={ids} onChange={setIds} options={source === 'organization' ? [{ value: 1, label: 'System Organization' }] : options.map((x) => ({ value: x.id, label: x.name || x.display_name }))} placeholder={t('search')} /><Button type="primary" disabled={!ids.length} onClick={async () => { await api.post(`/agent-templates/${detail.id}/assignments`, { source_type: source, target_ids: ids, policy: 'default' }); setIds([]); onChange() }}>{t('save')}</Button></Space><Table size="small" rowKey="id" dataSource={detail.assignments} columns={[{ title: t('scope'), dataIndex: 'source_type' }, { title: t('target'), dataIndex: 'target' }, { title: t('createdAt'), dataIndex: 'created_at' }, { title: t('actions'), render: (_: unknown, r: any) => <Button danger size="small" onClick={async () => { await api.delete(`/agent-templates/${detail.id}/assignments/${r.id}`); onChange() }}>{t('delete')}</Button> }]} /></> }

export function ProfilesV21() { const { t } = useI18n(); const [data, setData] = useState<Profile[]>([]); const [selected, setSelected] = useState<any>(); const [error, setError] = useState<unknown>(); useEffect(() => { api.get<Profile[]>('/profiles-v2').then(setData).catch(setError) }, []); const show = async (p: Profile) => { try { setSelected(await api.get<any>(`/profiles/${p.id}/effective-configuration`)) } catch (e) { setError(e) } }; return <>{page(t('profiles'), t('profileBoundary'))}<V21Error error={error} /><Card className="content-card"><Table rowKey="id" dataSource={data} columns={[{ title: t('name'), render: (_: unknown, r: Profile) => <Button type="link" onClick={() => show(r)}>{r.display_name}</Button> }, { title: t('owner'), dataIndex: 'user' }, { title: t('model'), dataIndex: 'model' }, { title: t('profileType'), render: (_: unknown, r: any) => <Tag color={r.profile_type === 'managed' ? 'blue' : 'default'}>{r.profile_type || 'personal'}</Tag> }, { title: t('status'), render: (_: unknown, r: Profile) => <V21Status value={r.status} /> }]} /></Card><Drawer width={900} title={`${t('details')} · ${selected?.profile_name || ''}`} open={!!selected} onClose={() => setSelected(undefined)}>{selected && <><Descriptions column={2} items={[{ key: '1', label: t('profileType'), children: selected.profile_type }, { key: '2', label: t('template'), children: `${selected.template?.name || 'Personal'} ${selected.template?.version ? `v${selected.template.version}` : ''}` }, { key: '3', label: t('model'), children: `${selected.model?.name || '—'} · ${selected.model?.source || ''}` }]} /><Title level={5}>Source Roles</Title><Space wrap>{(selected.source_roles || []).map((role: any) => <Tag key={role.id}>{role.name} · {role.source}</Tag>)}</Space><Title level={5}>{t('defaultSkills')}</Title><Table size="small" rowKey="id" dataSource={selected.skills} columns={[{ title: t('name'), dataIndex: 'display_name' }, { title: t('category'), dataIndex: 'category' }, { title: t('policy'), dataIndex: 'policy' }, { title: t('source'), dataIndex: 'source' }, { title: t('status'), render: (_: unknown, r: any) => r.enabled ? <V21Status value="active" /> : <V21Status value="blocked" /> }]} /><Title level={5}>{t('defaultKnowledge')}</Title><Table size="small" rowKey="id" dataSource={selected.knowledge} columns={[{ title: t('name'), dataIndex: 'name' }, { title: t('owner'), dataIndex: 'owner_department' }, { title: t('policy'), dataIndex: 'policy' }, { title: t('source'), dataIndex: 'source' }]} /></>}</Drawer></> }

export function RuntimesV21() {
  const { t } = useI18n()
  const [data, setData] = useState<any[]>([])
  const [selected, setSelected] = useState<any>()
  const [error, setError] = useState<unknown>()
  const [resourceOpen, setResourceOpen] = useState(false)
  const [resourceForm] = Form.useForm()
  const load = () => api.get<any[]>('/runtimes-v2').then(setData).catch(setError)
  useEffect(() => { void load() }, [])
  const open = async (r: any) => {
    try {
      const [detail, skills, executions, events] = await Promise.all([
        api.get<any>('/runtimes/' + r.id + '/detail'),
        api.get<any[]>('/runtimes/' + r.id + '/effective-skills'),
        api.get<any[]>('/runtimes/' + r.id + '/executions'),
        api.get<any[]>('/runtimes/' + r.id + '/events')
      ])
      setSelected({ ...detail, skills, executions, events })
    } catch (e) { setError(e) }
  }
  const control = async (id: number, action: string) => {
    try { await api.post('/runtimes/' + id + '/control', { action }); void load(); if (selected) void open({ id }) } catch (e) { setError(e) }
  }
  const editResources = () => {
    resourceForm.setFieldsValue({ template_id: selected.template_id, cpu_limit: selected.cpu_limit, memory_limit: selected.memory_limit, storage_limit: selected.storage_limit, profile_limit: selected.profile_limit, max_concurrent_jobs: selected.max_concurrent_jobs })
    setResourceOpen(true)
  }
  return <>
    {page(t('runtimeManagement'), t('runtimeBoundary'))}
    <Alert type='info' showIcon message={t('mockProvider')} description={t('runtimeSecurityBoundary')} style={{ marginBottom: 16 }} />
    <V21Error error={error} />
    <Card className='content-card'><Table rowKey='id' dataSource={data} columns={[{ title: t('runtimeId'), dataIndex: 'runtime_id' }, { title: t('owner'), dataIndex: 'user' }, { title: t('status'), render: (_: unknown, r: any) => <Space><V21Status value={r.desired_status || r.status} /><V21Status value={r.observed_status || r.status} /></Space> }, { title: t('cpuMemory'), render: (_: unknown, r: any) => r.cpu_limit + ' / ' + r.memory_limit }, { title: t('profiles'), dataIndex: 'profile_count' }, { title: t('actions'), render: (_: unknown, r: any) => <Space><Button size='small' onClick={() => open(r)}>{t('details')}</Button><Button size='small' onClick={() => control(r.id, r.status === 'running' ? 'stop' : 'start')}>{r.status === 'running' ? t('stop') : t('start')}</Button><Button size='small' onClick={() => control(r.id, 'restart')}>{t('restart')}</Button></Space> }]} /></Card>
    <Drawer width={1050} title={t('details') + ' · ' + (selected?.user || '')} open={!!selected} onClose={() => setSelected(undefined)}>{selected && <Tabs items={[{ key: 'overview', label: t('overviewTab'), children: <Descriptions column={2} items={[{ key: '1', label: t('runtimeId'), children: selected.runtime_id }, { key: '2', label: t('desiredStatus'), children: <V21Status value={selected.desired_status} /> }, { key: '3', label: t('observedStatus'), children: <V21Status value={selected.observed_status} /> }, { key: '4', label: t('template'), children: selected.template_id || '—' }]} /> }, { key: 'profiles', label: t('profiles'), children: <Table size='small' rowKey='id' dataSource={selected.profiles} columns={[{ title: t('name'), dataIndex: 'display_name' }, { title: t('profileType'), dataIndex: 'profile_type' }, { title: t('status'), render: (_: unknown, r: any) => <V21Status value={r.status} /> }]} /> }, { key: 'skills', label: t('defaultSkills'), children: <Table size='small' rowKey='id' dataSource={selected.skills} columns={[{ title: t('name'), dataIndex: 'display_name' }, { title: t('source'), dataIndex: 'source' }, { title: t('policy'), dataIndex: 'policy' }]} /> }, { key: 'executions', label: t('executions'), children: <Table size='small' rowKey='id' dataSource={selected.executions} columns={[{ title: t('executionId'), dataIndex: 'execution_id' }, { title: t('status'), render: (_: unknown, r: any) => <V21Status value={r.status} /> }, { title: t('risk'), render: (_: unknown, r: any) => <V21Status value={r.risk_level} /> }]} /> }, { key: 'resources', label: t('resources'), children: <Space direction='vertical' style={{ width: '100%' }}><Descriptions column={1} items={[{ key: '1', label: 'CPU', children: selected.cpu_limit }, { key: '2', label: t('memory'), children: selected.memory_limit }, { key: '3', label: t('storage'), children: selected.storage_limit }, { key: '4', label: t('profileLimit'), children: selected.profile_limit }, { key: '5', label: t('concurrentJobs'), children: selected.max_concurrent_jobs }]} /><Button onClick={editResources}>{t('edit')}</Button></Space> }, { key: 'controls', label: t('controls'), children: <Space><Button onClick={() => control(selected.id, 'start')}>{t('start')}</Button><Button onClick={() => control(selected.id, 'stop')}>{t('stop')}</Button><Button onClick={() => control(selected.id, 'restart')}>{t('restart')}</Button><Popconfirm title={t('killSwitchReason')} description={<Input.TextArea id='kill-reason' placeholder={t('killSwitchReason')} />} onConfirm={async () => { const reason = (document.getElementById('kill-reason') as HTMLTextAreaElement)?.value || 'Emergency demo stop'; try { await api.post('/runtimes/' + selected.id + '/kill-switch', { reason }); void open(selected) } catch (e) { setError(e) } }}><Button danger>{t('killSwitch')}</Button></Popconfirm></Space> }, { key: 'events', label: t('events'), children: <Table size='small' rowKey='id' dataSource={selected.events} columns={[{ title: t('type'), dataIndex: 'event_type' }, { title: t('description'), dataIndex: 'message' }, { title: t('createdAt'), dataIndex: 'created_at' }]} /> }]} />}</Drawer>
    <Modal title={t('resources')} open={resourceOpen} onCancel={() => setResourceOpen(false)} footer={null}><Form form={resourceForm} layout='vertical' onFinish={async (v) => { try { const result = await api.put<any>('/runtimes/' + selected.id, v); if (result?.status === 'pending') message.info(t('pendingApprovals')); else message.success(t('saved')); setResourceOpen(false); void load(); void open(selected) } catch (e) { setError(e) } }}><Form.Item name='cpu_limit' label='CPU' rules={[{ required: true }]}><Input /></Form.Item><Form.Item name='memory_limit' label={t('memory')} rules={[{ required: true }]}><Input /></Form.Item><Form.Item name='storage_limit' label={t('storage')} rules={[{ required: true }]}><Input /></Form.Item><Form.Item name='profile_limit' label={t('profileLimit')} rules={[{ required: true }]}><InputNumber min={1} style={{ width: '100%' }} /></Form.Item><Form.Item name='max_concurrent_jobs' label={t('concurrentJobs')} rules={[{ required: true }]}><InputNumber min={1} style={{ width: '100%' }} /></Form.Item><Form.Item name='template_id' label={t('template')}><InputNumber min={1} style={{ width: '100%' }} /></Form.Item><Button type='primary' htmlType='submit' block>{t('save')}</Button></Form></Modal>
  </>
}

export function KnowledgeBasesV21() { const { t } = useI18n(); const [data, setData] = useState<any[]>([]); const [selected, setSelected] = useState<any>(); const [items, setItems] = useState<any[]>([]); const [bindings, setBindings] = useState<any[]>([]); const [consumers, setConsumers] = useState<any>(); const [open, setOpen] = useState(false); const [kbOpen, setKbOpen] = useState(false); const [form] = Form.useForm(); const [kbForm] = Form.useForm(); const [bindingForm] = Form.useForm(); const [bindingOptions, setBindingOptions] = useState<any>({ departments: [], roles: [], profiles: [] }); const [error, setError] = useState<unknown>(); const load = () => api.get<any[]>('/knowledge-bases').then(setData).catch(setError); useEffect(() => { void load(); Promise.all([api.get<any[]>('/departments/tree'), api.get<any[]>('/roles/manage'), api.get<any[]>('/profiles-v2'), api.get<any[]>('/agent-templates')]).then(([departments, roles, profiles, agentTemplates]) => setBindingOptions({ departments: flattenDepartments(departments), roles, profiles, agentTemplates })).catch(setError) }, []); const show = async (kb: any) => { try { const [d, c, b] = await Promise.all([api.get<any[]>('/knowledge-bases/' + kb.id + '/items'), api.get<any>('/knowledge-bases/' + kb.id + '/consumers'), api.get<any[]>('/knowledge-bases/' + kb.id + '/bindings')]); setSelected(kb); setItems(d); setConsumers(c); setBindings(b) } catch (e) { setError(e) } }; const edit = (item?: any) => { form.resetFields(); if (item) form.setFieldsValue(item); setOpen(true) }; return <>{page(t('knowledge'), t('knowledgeBoundary'), <Button type="primary" icon={<BookOutlined />} onClick={() => { kbForm.resetFields(); setKbOpen(true) }}>{t('create')}</Button>)}<V21Error error={error} /><Card className="content-card"><Table rowKey="id" dataSource={data} columns={[{ title: t('name'), render: (_: unknown, r: any) => <Button type="link" onClick={() => show(r)}>{r.name}</Button> }, { title: t('description'), dataIndex: 'description' }, { title: t('documents'), dataIndex: 'document_count' }, { title: t('status'), render: (_: unknown, r: any) => <V21Status value={r.status} /> }]} /></Card><Drawer width={1100} title={`${t('details')} · ${selected?.name || ''}`} open={!!selected} onClose={() => setSelected(undefined)}>{selected && <Tabs items={[{ key: 'content', label: t('content'), children: <><Space style={{ marginBottom: 16 }}><Button type="primary" onClick={() => edit()}>{t('createDocument')}</Button><Input.Search allowClear placeholder={t('search')} onSearch={async (q) => setItems(await api.get<any[]>(`/knowledge-bases/${selected.id}/items?q=${encodeURIComponent(q)}`))} /></Space><Table rowKey="id" dataSource={items} columns={[{ title: t('type'), dataIndex: 'type' }, { title: t('name'), dataIndex: 'title' }, { title: t('status'), render: (_: unknown, r: any) => <V21Status value={r.status} /> }, { title: t('indexStatus'), render: (_: unknown, r: any) => <V21Status value={r.index_status} /> }, { title: t('updatedAt'), dataIndex: 'updated_at' }, { title: t('actions'), render: (_: unknown, r: any) => <Space><Button size="small" onClick={() => edit(r)}>{t('edit')}</Button><Button size="small" onClick={async () => { await api.post(`/knowledge-items/${r.id}/publish`, {}); show(selected) }}>{t('publish')}</Button><Popconfirm title={t('delete')} onConfirm={async () => { await api.delete(`/knowledge-items/${r.id}`); show(selected) }}><Button size="small" danger>{t('delete')}</Button></Popconfirm></Space> }]} /></> }, { key: 'bindings', label: t('bindings'), children: <><Table size="small" rowKey="id" dataSource={bindings} columns={[{ title: t('type'), dataIndex: 'binding_type' }, { title: t('scope'), dataIndex: 'scope' }, { title: t('department'), render: (_: unknown, r: any) => r.department_id ? <Link to={'/organization?department=' + r.department_id}>{r.department}</Link> : '—' }, { title: t('role'), render: (_: unknown, r: any) => r.role_id ? <Link to={'/roles?id=' + r.role_id}>{r.role}</Link> : '—' }, { title: t('profile'), render: (_: unknown, r: any) => r.profile_id ? <Link to={'/profiles?id=' + r.profile_id}>{r.profile}</Link> : '—' }, { title: t('agentTemplates'), render: (_: unknown, r: any) => r.agent_template_id ? <Link to={'/agent-templates?id=' + r.agent_template_id}>{r.agent_template}</Link> : '—' }, { title: t('actions'), render: (_: unknown, r: any) => <Popconfirm title={t('delete')} onConfirm={async () => { try { await api.delete('/knowledge-bases/' + selected.id + '/bindings/' + r.id); show(selected) } catch (e) { setError(e) } }}><Button danger size='small'>{t('delete')}</Button></Popconfirm> }]} /><Form form={bindingForm} layout="inline" onFinish={async (v) => { try { await api.post('/knowledge-bases/' + selected.id + '/bindings/v2', v); message.success(t('saved')); bindingForm.resetFields(); show(selected) } catch (e) { setError(e) } }}><Form.Item name="binding_type" label={t('type')} initialValue="department"><Select options={['organization', 'department', 'role', 'profile'].map((v) => ({ value: v, label: v }))} /></Form.Item><Form.Item name="organization_id" label="Organization"><Select allowClear options={[{ value: 1, label: "Current organization" }]} /></Form.Item><Form.Item name="department_id" label={t('department' )}><Select allowClear showSearch optionFilterProp="label" options={bindingOptions.departments.map((v: any) => ({ value: v.id, label: v.name }))} /></Form.Item><Form.Item name="agent_template_id" label={t('agentTemplates' )}><Select allowClear showSearch optionFilterProp="label" options={(bindingOptions.agentTemplates || []).map((v: any) => ({ value: v.id, label: v.display_name || v.name }))} /></Form.Item><Form.Item name="role_id" label={t('role')}><Select allowClear showSearch optionFilterProp="label" options={bindingOptions.roles.map((v: any) => ({ value: v.id, label: v.name }))} /></Form.Item><Form.Item name="profile_id" label={t('profile')}><Select allowClear showSearch optionFilterProp="label" options={bindingOptions.profiles.map((v: any) => ({ value: v.id, label: v.display_name }))} /></Form.Item><Form.Item name="policy" label={t('policy')} initialValue="default"><Select options={['mandatory', 'default', 'optional'].map((v) => ({ value: v, label: v }))} /></Form.Item><Button type="primary" htmlType="submit">{t('save')}</Button></Form></>}, { key: 'consumers', label: t('effectiveConsumers'), children: <Descriptions column={1} items={[{ key: '1', label: t('directBindings'), children: consumers?.direct_bindings }, { key: '2', label: t('effectiveUsers'), children: consumers?.effective_user_count }, { key: '3', label: t('effectiveProfiles'), children: consumers?.effective_profile_count }]} /> }, { key: 'settings', label: t('settings'), children: <Alert type="info" message="MockKnowledgeProvider" description={t('knowledgeBoundary')} /> }]} />}</Drawer><Modal title={t('knowledge')} open={kbOpen} onCancel={() => setKbOpen(false)} footer={null}><Form form={kbForm} layout="vertical" onFinish={async (v) => { try { await api.post('/knowledge-bases', { ...v, visibility: v.visibility || 'department' }); message.success(t('created')); setKbOpen(false); load() } catch (e) { setError(e) } }}><Form.Item name="name" label={t('name')} rules={[{ required: true }]}><Input /></Form.Item><Form.Item name="description" label={t('description')}><Input.TextArea /></Form.Item><Form.Item name="visibility" label={t('visibility')} initialValue="department"><Select options={['organization', 'department', 'private'].map((v) => ({ value: v, label: v }))} /></Form.Item><Button type="primary" htmlType="submit" block>{t('save')}</Button></Form></Modal><Modal title={t('content')} open={open} onCancel={() => setOpen(false)} footer={null} width={760}><Form form={form} layout="vertical" onFinish={async (v) => { try { if (v.id) await api.put(`/knowledge-items/${v.id}`, v); else await api.post(`/knowledge-bases/${selected?.id}/items`, v); message.success(t('saveDraft')); setOpen(false); show(selected) } catch (e) { setError(e) } }}><Form.Item name="id" hidden><Input /></Form.Item><Form.Item name="type" label={t('type')} initialValue="markdown"><Select options={['background', 'qa', 'markdown', 'procedure'].map((v) => ({ value: v, label: v }))} /></Form.Item><Form.Item name="title" label={t('name')} rules={[{ required: true }]}><Input /></Form.Item><Form.Item name="content" label={t('content')}><Input.TextArea rows={10} /></Form.Item><Form.Item name="question" label={t('question')}><Input.TextArea /></Form.Item><Form.Item name="answer" label={t('answer')}><Input.TextArea /></Form.Item><Form.Item name="purpose" label={t('purpose')}><Input /></Form.Item><Form.Item name="prerequisites" label={t('prerequisites')}><Input /></Form.Item><Form.Item name="steps" label={t('steps')}><Select mode="tags" /></Form.Item><Form.Item name="tags" label={t('tags')}><Select mode="tags" /></Form.Item><Button type="primary" htmlType="submit" block>{t('saveDraft')}</Button></Form></Modal></>
}

export function ExecutionLogsV21() { const { t } = useI18n(); const [data, setData] = useState<any[]>([]); const [detail, setDetail] = useState<any>(); const [filters, setFilters] = useState<Record<string, string>>({}); const [error, setError] = useState<unknown>(); const load = (next = filters) => { const q = Object.entries(next).filter(([, v]) => v).map(([k, v]) => `${k}=${encodeURIComponent(v)}`).join('&'); api.get<any[]>(`/executions${q ? `?${q}` : ''}`).then(setData).catch(setError) }; useEffect(() => { load({}) }, []); const set = (key: string, value: string) => setFilters((x) => ({ ...x, [key]: value })); return <>{page(t('executions'), t('executionBoundary'))}<V21Error error={error} /><Card className="content-card" extra={<Space><Select allowClear placeholder={t('risk')} onChange={(v) => set('risk_level', v)} options={['low', 'medium', 'high', 'critical'].map((v) => ({ value: v }))} /><Select allowClear placeholder={t('status')} onChange={(v) => set('status', v)} options={['completed', 'waiting_approval', 'rejected', 'cancelled'].map((v) => ({ value: v }))} /><Button type="primary" onClick={() => load()}>{t('filter')}</Button></Space>}><Table rowKey="id" dataSource={data} scroll={{ x: 1200 }} columns={[{ title: t('executionId'), render: (_: unknown, r: any) => <Button type="link" onClick={async () => setDetail(await api.get<any>(`/executions/${r.id}`))}>{r.execution_id}</Button> }, { title: t('owner'), dataIndex: 'user' }, { title: t('profile'), dataIndex: 'profile' }, { title: t('runtime'), dataIndex: 'runtime' }, { title: t('model'), dataIndex: 'model' }, { title: t('status'), render: (_: unknown, r: any) => <V21Status value={r.status} /> }, { title: t('risk'), render: (_: unknown, r: any) => <Space><V21Status value={r.risk_level} /><Text type="secondary">{r.risk_reason}</Text></Space> }, { title: t('createdAt'), dataIndex: 'created_at' }]} /></Card><Drawer width={900} title={`${t('details')} · ${detail?.execution_id || ''}`} open={!!detail} onClose={() => setDetail(undefined)}>{detail && <Tabs items={[{ key: 'summary', label: t('overviewTab'), children: <Descriptions column={2} items={[{ key: '1', label: t('owner'), children: detail.user }, { key: '2', label: t('profile'), children: detail.profile }, { key: '3', label: t('model'), children: detail.model }, { key: '4', label: t('status'), children: <V21Status value={detail.status} /> }]} /> }, { key: 'timeline', label: t('timeline'), children: <Table size="small" rowKey="created_at" dataSource={detail.timeline} columns={[{ title: t('event'), dataIndex: 'event_type' }, { title: t('description'), dataIndex: 'message' }, { title: t('createdAt'), dataIndex: 'created_at' }]} /> }, { key: 'tools', label: t('tools'), children: <Space wrap>{(detail.tools || []).map((x: string) => <Tag key={x}>{x}</Tag>)}</Space> }, { key: 'skills', label: t('skills'), children: <Space wrap>{(detail.skills || []).map((x: string) => <Tag key={x}>{x}</Tag>)}</Space> }, { key: 'risk', label: t('risk'), children: <Alert type={detail.risk_level === 'critical' ? 'error' : 'warning'} message={detail.risk_level} description={detail.risk_reason} /> }, { key: 'approval', label: t('approvals'), children: detail.approval_request_id ? <Link to="/approvals">{t('approvalReviewed')}</Link> : <Empty description={t('empty')} /> }]} />}</Drawer></>
}

export function AuditLogsV21() {
  const { t } = useI18n()
  const [data, setData] = useState<any[]>([])
  const [catalog, setCatalog] = useState<any>({ categories: [], actions: {} })
  const [refs, setRefs] = useState<any>({ users: [], departments: [], profiles: [], runtimes: [], skills: [], models: [] })
  const [filters, setFilters] = useState<Record<string, string>>({})
  const [error, setError] = useState<unknown>()
  const toQuery = (values: Record<string, string>) => Object.entries(values).filter(([, value]) => value).map(([key, value]) => key + "=" + encodeURIComponent(value)).join("&")
  const load = async (values = filters) => { try { const query = toQuery(values); setData(await api.get<any[]>("/audit-logs/v2" + (query ? "?" + query : ""))); setError(undefined) } catch (e) { setError(e) } }
  useEffect(() => { Promise.all([api.get<any>("/audit-catalog"), api.get<any[]>("/users"), api.get<any[]>("/departments/tree"), api.get<any[]>("/profiles-v2"), api.get<any[]>("/runtimes"), api.get<any[]>("/skills"), api.get<any[]>("/models")]).then(([c, users, departments, profiles, runtimes, skills, models]) => { setCatalog(c); setRefs({ users, departments: flattenDepartments(departments), profiles, runtimes, skills, models }); void load({}) }).catch(setError) }, [])
  const setFilter = (key: string, value?: string | number) => setFilters((old) => ({ ...old, [key]: value === undefined ? "" : String(value) }))
  const setCategory = (value?: string) => setFilters((old) => ({ ...old, category: value || "", action: "" }))
  const exportFile = async (format: string) => { try { const query = toQuery(filters); const blob = await api.download("/audit-logs/export?format=" + format + (query ? "&" + query : "")); const anchor = document.createElement("a"); anchor.href = URL.createObjectURL(blob); anchor.download = "audit-export." + format; anchor.click(); URL.revokeObjectURL(anchor.href) } catch (e) { setError(e) } }
  const select = (placeholder: string, key: string, options: any[], onChange = (value: any) => setFilter(key, value)) => <Select allowClear showSearch optionFilterProp="label" placeholder={placeholder} value={filters[key] || undefined} options={options} onChange={onChange} style={{ minWidth: 150 }} />
  return <>{page(t("audit"), t("auditBoundary"), <Space><Button onClick={() => void exportFile("csv")}>{t("exportCsv")}</Button><Button onClick={() => void exportFile("json")}>{t("exportJson")}</Button></Space>)}<V21Error error={error} /><Card className="content-card" title={t("audit")}><Space direction="vertical" style={{ width: "100%" }}><Space wrap>{<DatePicker.RangePicker onChange={(values) => setFilters((old) => ({ ...old, time_from: values?.[0]?.startOf("day").toISOString() || "", time_to: values?.[1]?.endOf("day").toISOString() || "" }))} />}{select(t("category"), "category", (catalog.categories || []).map((value: string) => ({ value, label: value })), setCategory)}{select(t("actionFilter"), "action", (catalog.actions?.[filters.category] || []).map((value: string) => ({ value, label: value })))}{select(t("actor"), "actor_id", refs.users.map((value: any) => ({ value: value.id, label: value.display_name + " · " + value.username })))}{select(t("department"), "department_id", refs.departments.map((value: any) => ({ value: value.id, label: value.name })))}{select(t("resourceType"), "resource_type", ["user", "department", "role", "profile_template", "profile", "runtime", "execution", "skill", "knowledge_base", "settings", "approval", "audit_log"].map((value) => ({ value, label: value })))}{select(t("result"), "result", ["success", "denied", "failure"].map((value) => ({ value, label: value })))}{select(t("risk"), "risk_level", ["low", "medium", "high", "critical"].map((value) => ({ value, label: value })))}<Input allowClear placeholder={t("search")} value={filters.search || ""} onChange={(event) => setFilter("search", event.target.value)} /><Button type="primary" onClick={() => void load()}>{t("filter")}</Button></Space><Space wrap><Text type="secondary">{t("advancedFilters")}</Text>{select(t("runtime"), "runtime_id", refs.runtimes.map((value: any) => ({ value: value.id, label: value.runtime_id || value.id })))}{select(t("profile"), "profile_id", refs.profiles.map((value: any) => ({ value: value.id, label: value.display_name || value.name })))}{select(t("skill"), "skill_id", refs.skills.map((value: any) => ({ value: value.id, label: value.display_name || value.name })))}{select(t("model"), "model_id", refs.models.map((value: any) => ({ value: value.id, label: value.display_name || value.name })))}<Input allowClear placeholder={t("resourceId")} value={filters.resource_id || ""} onChange={(event) => setFilter("resource_id", event.target.value)} /><Input allowClear placeholder={t("sourceIp")} value={filters.ip_address || ""} onChange={(event) => setFilter("ip_address", event.target.value)} /><Input allowClear placeholder={t("requestId")} value={filters.request_id || ""} onChange={(event) => setFilter("request_id", event.target.value)} /></Space></Space><Table rowKey="id" dataSource={data} scroll={{ x: 1250 }} columns={[{ title: t("createdAt"), dataIndex: "created_at" }, { title: t("actor"), dataIndex: "actor" }, { title: t("category"), dataIndex: "category" }, { title: t("actions"), dataIndex: "action_label" }, { title: t("resource"), render: (_: unknown, value: any) => (value.resource_type || "") + " #" + value.resource_id }, { title: t("result"), dataIndex: "result" }, { title: t("risk"), render: (_: unknown, value: any) => <Space><V21Status value={value.risk_level} /><Text type="secondary">{value.risk_reason}</Text></Space> }, { title: t("ip"), dataIndex: "ip_address" }, { title: t("requestId"), dataIndex: "request_id" }]} /></Card></>
}